<script setup lang="ts">
import { onMounted, ref } from 'vue';import http from '@/api/http';import { ElMessage,ElMessageBox } from 'element-plus';import type { Dict } from '@/types'
const todo=ref<Dict[]>([]),done=ref<Dict[]>([]),tab=ref('todo');async function load(){[todo.value,done.value]=await Promise.all([http.get('/workflow/tasks'),http.get('/workflow/tasks/done')])}async function decide(row:Dict,action:'approve'|'reject'){const {value}=await ElMessageBox.prompt(action==='approve'?'填写审批意见（可选）':'填写驳回原因','审批处理',{inputValidator:v=>action==='approve'||!!v||'驳回原因不能为空'});await http.post(`/workflow/${row.id}/${action}`,{comment:value});ElMessage.success(action==='approve'?'审批已通过':'已驳回');load()}onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><h1>审批中心</h1><p>Flowable统一管理采购申请与采购订单审批</p></div><el-button @click="load">刷新</el-button></div><div class="panel panel-pad"><el-tabs v-model="tab"><el-tab-pane :label="`待办 (${todo.length})`" name="todo"><el-table :data="todo"><el-table-column prop="name" label="审批节点"/><el-table-column prop="businessKey" label="业务单据"/><el-table-column prop="createdAt" label="到达时间"/><el-table-column label="操作" width="160"><template #default="s"><el-button link type="primary" @click="decide(s.row,'approve')">通过</el-button><el-button link type="danger" @click="decide(s.row,'reject')">驳回</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane :label="`已办 (${done.length})`" name="done"><el-table :data="done"><el-table-column prop="name" label="审批节点"/><el-table-column prop="processInstanceId" label="流程实例"/><el-table-column prop="createdAt" label="处理时间"/></el-table></el-tab-pane></el-tabs></div></div></template>
